-- MedInsure warehouse DDL (Deliverable 2)
-- Run after 00_schemas.sql:
--   psql -h localhost -p 5432 -U postgres -d medinsure -f sql/02_dw_ddl.sql
-- Surrogate keys use GENERATED BY DEFAULT so NA placeholder rows can use key = 0.
-- SCD2 uses brief naming: effective_start / effective_end / is_current (inclusive end).

BEGIN;

DROP TABLE IF EXISTS dw.fact_claim_line CASCADE;
DROP TABLE IF EXISTS dw.fact_claim CASCADE;
DROP TABLE IF EXISTS dw.dim_member CASCADE;
DROP TABLE IF EXISTS dw.dim_provider CASCADE;
DROP TABLE IF EXISTS dw.dim_diagnosis CASCADE;
DROP TABLE IF EXISTS dw.dim_procedure CASCADE;
DROP TABLE IF EXISTS dw.dim_plan CASCADE;
DROP TABLE IF EXISTS dw.dim_date CASCADE;

-- ---------------------------------------------------------------------------
-- dim_date (role-playing calendar; populated in ETL via GENERATE_SERIES)
-- ---------------------------------------------------------------------------
CREATE TABLE dw.dim_date (
    date_key        INT PRIMARY KEY,              -- YYYYMMDD, e.g. 20250615
    full_date       DATE NOT NULL UNIQUE,
    year            INT  NOT NULL,
    quarter         INT  NOT NULL,
    month           INT  NOT NULL,
    month_name      TEXT NOT NULL,
    day_of_month    INT  NOT NULL,
    day_of_week     INT  NOT NULL,                 -- ISO: 1 = Monday … 7 = Sunday
    day_name        TEXT NOT NULL,
    is_weekend      BOOLEAN NOT NULL
);

-- ---------------------------------------------------------------------------
-- dim_plan (SCD Type 1 — current plan catalog attributes)
-- ---------------------------------------------------------------------------
CREATE TABLE dw.dim_plan (
    plan_key        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    plan_id         INT  NOT NULL UNIQUE,         -- natural key from OLTP plan_types
    plan_code       VARCHAR(20) NOT NULL,
    plan_name       VARCHAR(100) NOT NULL,
    plan_type       VARCHAR(20) NOT NULL,         -- HMO | PPO | EPO | HDHP
    deductible      NUMERIC(10,2) NOT NULL CHECK (deductible >= 0),
    oop_max         NUMERIC(10,2) NOT NULL CHECK (oop_max >= 0)
);

-- ---------------------------------------------------------------------------
-- dim_diagnosis (SCD Type 1 — ICD-10 reference)
-- ---------------------------------------------------------------------------
CREATE TABLE dw.dim_diagnosis (
    diagnosis_key   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    diagnosis_code  VARCHAR(10) NOT NULL UNIQUE,
    description     VARCHAR(200) NOT NULL,
    category        VARCHAR(80) NOT NULL          -- hierarchy used by spend-by-category analytics
);

-- ---------------------------------------------------------------------------
-- dim_procedure (SCD Type 1 — CPT reference)
-- ---------------------------------------------------------------------------
CREATE TABLE dw.dim_procedure (
    procedure_key   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    procedure_code  VARCHAR(10) NOT NULL UNIQUE,
    description     VARCHAR(200) NOT NULL,
    category        VARCHAR(80) NOT NULL
);

-- ---------------------------------------------------------------------------
-- dim_member (SCD Type 2 — plan / state / zip history)
-- ---------------------------------------------------------------------------
CREATE TABLE dw.dim_member (
    member_key      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    member_id       INT  NOT NULL,                -- natural key from OLTP
    first_name      VARCHAR(60) NOT NULL,
    last_name       VARCHAR(60) NOT NULL,
    date_of_birth   DATE,
    gender          CHAR(1),
    enrollment_date DATE NOT NULL,
    plan_id         INT  NOT NULL,                 -- SCD2 tracked
    state           CHAR(2) NOT NULL,              -- SCD2 tracked
    zip_code        VARCHAR(10) NOT NULL,          -- SCD2 tracked
    effective_start DATE NOT NULL,
    effective_end   DATE NOT NULL DEFAULT DATE '9999-12-31',  -- inclusive
    is_current      BOOLEAN NOT NULL DEFAULT TRUE,
    CHECK (effective_start <= effective_end)
);
CREATE INDEX idx_dim_member_nk_current
    ON dw.dim_member (member_id, is_current);
CREATE INDEX idx_dim_member_nk_range
    ON dw.dim_member (member_id, effective_start, effective_end);

-- ---------------------------------------------------------------------------
-- dim_provider (SCD Type 2 — network_status / specialty history)
-- ---------------------------------------------------------------------------
CREATE TABLE dw.dim_provider (
    provider_key           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    provider_id            INT  NOT NULL,
    provider_name          VARCHAR(120) NOT NULL,
    provider_type          VARCHAR(40) NOT NULL,  -- physician | hospital | facility
    specialty              VARCHAR(60) NOT NULL,  -- SCD2 tracked
    network_status         VARCHAR(20) NOT NULL,  -- in_network | out_of_network (SCD2)
    network_effective_date DATE NOT NULL,         -- used by anachronistic-claim DQ
    effective_start        DATE NOT NULL,
    effective_end          DATE NOT NULL DEFAULT DATE '9999-12-31',
    is_current             BOOLEAN NOT NULL DEFAULT TRUE,
    CHECK (effective_start <= effective_end)
);
CREATE INDEX idx_dim_provider_nk_current
    ON dw.dim_provider (provider_id, is_current);
CREATE INDEX idx_dim_provider_nk_range
    ON dw.dim_provider (provider_id, effective_start, effective_end);

-- ---------------------------------------------------------------------------
-- fact_claim — grain: one row per adjudicated claim header (transaction fact)
-- ---------------------------------------------------------------------------
CREATE TABLE dw.fact_claim (
    claim_key           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    claim_id            INT  NOT NULL UNIQUE,     -- degenerate dimension + idempotency
    service_date_key    INT  NOT NULL REFERENCES dw.dim_date (date_key),
    processed_date_key  INT  NOT NULL REFERENCES dw.dim_date (date_key),
    member_key          BIGINT NOT NULL REFERENCES dw.dim_member (member_key),
    provider_key        BIGINT NOT NULL REFERENCES dw.dim_provider (provider_key),
    diagnosis_key       BIGINT NOT NULL REFERENCES dw.dim_diagnosis (diagnosis_key), -- 0 = NA
    plan_key            BIGINT NOT NULL REFERENCES dw.dim_plan (plan_key),
    claim_type          VARCHAR(30) NOT NULL,     -- professional | institutional | pharmacy_medical
    claim_status        VARCHAR(20) NOT NULL,     -- paid | denied | partial
    total_allowed       NUMERIC(12,2) NOT NULL CHECK (total_allowed >= 0),
    total_paid          NUMERIC(12,2) NOT NULL CHECK (total_paid >= 0)
);
-- FK indexes (brief requirement)
CREATE INDEX idx_fact_claim_service_date   ON dw.fact_claim (service_date_key);
CREATE INDEX idx_fact_claim_processed_date ON dw.fact_claim (processed_date_key);
CREATE INDEX idx_fact_claim_member         ON dw.fact_claim (member_key);
CREATE INDEX idx_fact_claim_provider       ON dw.fact_claim (provider_key);
CREATE INDEX idx_fact_claim_diagnosis      ON dw.fact_claim (diagnosis_key);
CREATE INDEX idx_fact_claim_plan           ON dw.fact_claim (plan_key);

-- ---------------------------------------------------------------------------
-- fact_claim_line — grain: one row per service line (transaction fact)
-- ---------------------------------------------------------------------------
CREATE TABLE dw.fact_claim_line (
    claim_line_key      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    claim_line_id       BIGINT NOT NULL UNIQUE,   -- degenerate + idempotency
    claim_key           BIGINT NOT NULL REFERENCES dw.fact_claim (claim_key),
    claim_id            INT  NOT NULL,            -- degenerate; supports header lookup by natural key
    service_date_key    INT  NOT NULL REFERENCES dw.dim_date (date_key),
    member_key          BIGINT NOT NULL REFERENCES dw.dim_member (member_key),
    provider_key        BIGINT NOT NULL REFERENCES dw.dim_provider (provider_key),
    plan_key            BIGINT NOT NULL REFERENCES dw.dim_plan (plan_key),
    procedure_key       BIGINT NOT NULL REFERENCES dw.dim_procedure (procedure_key), -- 0 = NA
    line_number         SMALLINT NOT NULL CHECK (line_number > 0),
    line_allowed        NUMERIC(12,2) NOT NULL CHECK (line_allowed >= 0),
    line_paid           NUMERIC(12,2) NOT NULL CHECK (line_paid >= 0)
);
CREATE INDEX idx_fact_claim_line_claim_key  ON dw.fact_claim_line (claim_key);
CREATE INDEX idx_fact_claim_line_claim_id   ON dw.fact_claim_line (claim_id);
CREATE INDEX idx_fact_claim_line_service    ON dw.fact_claim_line (service_date_key);
CREATE INDEX idx_fact_claim_line_member     ON dw.fact_claim_line (member_key);
CREATE INDEX idx_fact_claim_line_provider   ON dw.fact_claim_line (provider_key);
CREATE INDEX idx_fact_claim_line_plan       ON dw.fact_claim_line (plan_key);
CREATE INDEX idx_fact_claim_line_procedure  ON dw.fact_claim_line (procedure_key);

-- ---------------------------------------------------------------------------
-- Not Applicable placeholder rows (key = 0) for optional dimension FKs
-- Member/provider unmatched claims are dead-lettered — not mapped to NA.
-- ---------------------------------------------------------------------------
INSERT INTO dw.dim_plan (plan_key, plan_id, plan_code, plan_name, plan_type, deductible, oop_max)
VALUES (0, 0, 'N/A', 'Not Applicable', 'N/A', 0, 0);

INSERT INTO dw.dim_diagnosis (diagnosis_key, diagnosis_code, description, category)
VALUES (0, 'N/A', 'Not Applicable', 'Not Applicable');

INSERT INTO dw.dim_procedure (procedure_key, procedure_code, description, category)
VALUES (0, 'N/A', 'Not Applicable', 'Not Applicable');

INSERT INTO dw.dim_member (
    member_key, member_id, first_name, last_name, enrollment_date,
    plan_id, state, zip_code, effective_start, effective_end, is_current
)
VALUES (
    0, 0, 'N/A', 'N/A', DATE '1900-01-01',
    0, 'XX', '00000', DATE '1900-01-01', DATE '9999-12-31', TRUE
);

INSERT INTO dw.dim_provider (
    provider_key, provider_id, provider_name, provider_type, specialty,
    network_status, network_effective_date, effective_start, effective_end, is_current
)
VALUES (
    0, 0, 'Not Applicable', 'N/A', 'N/A',
    'N/A', DATE '1900-01-01', DATE '1900-01-01', DATE '9999-12-31', TRUE
);

-- Keep identity sequences above reserved key 0
SELECT setval(pg_get_serial_sequence('dw.dim_plan', 'plan_key'), 1, false);
SELECT setval(pg_get_serial_sequence('dw.dim_diagnosis', 'diagnosis_key'), 1, false);
SELECT setval(pg_get_serial_sequence('dw.dim_procedure', 'procedure_key'), 1, false);
SELECT setval(pg_get_serial_sequence('dw.dim_member', 'member_key'), 1, false);
SELECT setval(pg_get_serial_sequence('dw.dim_provider', 'provider_key'), 1, false);

COMMIT;
